            originate(router)

    database_sequence, databases = _flood_to_fixed(
        databases, ordered_nodes, active_adjacency, down_nodes
    )
    rounds = _round_views(
        database_sequence, ordered_nodes, active_adjacency, down_nodes
    )
    return rounds, databases, numbers

